let streakMonth='';
const streakFlame='<svg viewBox="0 0 32 40" aria-hidden="true"><path fill="currentColor" d="M18 1c2 10-7 12-3 19 3-2 4-5 4-8 9 7 13 15 8 22-5 8-20 8-24-2C-2 21 9 15 10 7c4 2 5 6 4 9 4-5 5-9 4-15Z"/><path fill="#fff" d="M17 23c1 5-5 5-3 10-5-1-5-5-2-8-1 3 1 4 2 4 0-3 2-4 3-6Z"/></svg>';
function streakSummary(){return DojoStreaks.summary(state.days,dayKey());}
function streakWeek(){const today=dayKey(),start=G.weekKey(),set=new Set(streakSummary().days);return `<div class="streak-week">${['S','T','Q','Q','S','S','D'].map((label,i)=>{const day=G.shiftDay(start,i),done=set.has(day);return `<div class="${done?'done ':''}${day===today?'today ':''}${day>today?'future':''}" aria-label="${day.split('-').reverse().join('/')}: ${done?'atividade concluída':day===today?'hoje, prática pendente':day>today?'dia futuro':'sem atividade registrada'}"><small>${label}</small><span>${done?'✓':Number(day.slice(-2))}</span></div>`;}).join('')}</div>`;}
function streakWidget(){const s=streakSummary();return `<div class="side-card streak-card"><div class="streak-title"><span class="streak-flame">${streakFlame}</span><div><h3>Sequência do dojo</h3><p><strong>${s.current}</strong> ${s.current===1?'dia seguido':'dias seguidos'}</p></div></div>${streakWeek()}<p>${s.todayDone?'Dia marcado! Sua atividade de hoje já conta.':'Conclua uma atividade para marcar o dia de hoje.'}</p><button class="outline" data-view="sequence">Calendário e lembretes →</button></div>`;}
function sequencePage(){const today=dayKey(),s=streakSummary();if(!streakMonth||streakMonth>today.slice(0,7))streakMonth=today.slice(0,7);const name=new Date(streakMonth+'-01T12:00:00Z').toLocaleDateString('pt-BR',{month:'long',year:'numeric',timeZone:'UTC'});return `<section class="animate-in sequence-page"><div class="eyebrow">UM POUCO A CADA DIA</div><h1>Sua sequência no dojo</h1><p class="intro">Um dia conta quando você conclui uma atividade, mesmo que ainda esteja aprendendo. Abrir o app ou só ouvir uma palavra não marca o calendário.</p>${DojoMascot.status(state.days,today)}<div class="sequence-summary"><article><span class="streak-flame">${streakFlame}</span><b>${s.current}</b><span>dias seguidos</span></article><article><b>${s.best}</b><span>seu recorde</span></article><article><b>${s.total}</b><span>dias de prática</span></article></div><div class="sequence-grid"><div class="info-panel"><div class="calendar-heading"><button class="outline" data-streak-month="-1" aria-label="Mês anterior">←</button><h2>${name}</h2><button class="outline" data-streak-month="1" aria-label="Mês seguinte" ${streakMonth>=today.slice(0,7)?'disabled':''}>→</button></div><div class="streak-calendar"><div class="calendar-weekday">SEG</div><div class="calendar-weekday">TER</div><div class="calendar-weekday">QUA</div><div class="calendar-weekday">QUI</div><div class="calendar-weekday">SEX</div><div class="calendar-weekday">SÁB</div><div class="calendar-weekday">DOM</div>${DojoStreaks.calendar(state.days,streakMonth,today).map(c=>c.day?`<div class="calendar-day ${c.done?'done ':''}${c.today?'today ':''}${c.future?'future':''}" ${c.today?'aria-current="date"':''} aria-label="${c.day.split('-').reverse().join('/')}: ${c.done?'prática concluída':c.today?'hoje, ainda não marcado':c.future?'dia futuro':'sem atividade registrada'}"><span>${c.number}</span>${c.done?'<small aria-hidden="true">✓</small>':''}</div>`:'<div aria-hidden="true"></div>').join('')}</div><p class="calendar-legend"><span>✓ Atividade concluída</span><span>○ Contorno: hoje</span></p><p class="week-note">O dia vira à meia-noite de Brasília. Duas atividades no mesmo dia marcam um único dia.</p></div><aside><div class="info-panel"><h2>${s.todayDone?'Hoje já está marcado!':'Vamos dar um passo hoje?'}</h2><p>${s.todayDone?'Você cuidou da sua sequência. Volte amanhã no seu ritmo.':s.current?`Sua sequência é de ${s.current} ${s.current===1?'dia':'dias'}. Uma atividade concluída mantém o caminho de hoje.`:'Cada dia é uma chance de recomeçar. Seu recorde continua guardado.'}</p><button class="primary" data-view="home">${s.todayDone?'Voltar à jornada':'Escolher uma atividade'} →</button><h3>Próximo marco: ${s.next} dias</h3><div class="track"><span style="width:${Math.min(100,s.current/s.next*100)}%"></span></div><p class="week-note">Se passar um dia sem atividade, a sequência recomeça. Seu progresso e suas fases continuam salvos.</p></div><div class="info-panel"><h2>Marcos de constância</h2><div class="streak-badges">${[3,7,14,30,60,100].map(n=>`<span class="${s.best>=n?'earned':''}" aria-label="${n} dias: ${s.best>=n?'conquistado':'por conquistar'}">${s.best>=n?'✦':'○'} ${n} dias</span>`).join('')}</div></div></aside></div>${DojoPush.markup()}</section>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-streak-month]');if(!b)return;const d=new Date(streakMonth+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+Number(b.dataset.streakMonth));const next=d.toISOString().slice(0,7);if(next<=dayKey().slice(0,7)&&next>='2000-01'){streakMonth=next;render('sequence');}});
